// Texte mit eingesetzten Werten (Zahlen, Namen). Gruppen werden selbst wieder übersetzt.
(() => {
  const D = window.XYNTAL_EN;
  // Teile übersetzen: erst Wörterbuch, dann die einfachen Muster (ohne das allgemeine „A · B“-Muster)
  const t = (s) => {
    if (D[s] !== undefined) return D[s];
    for (const [re, rep] of window.XYNTAL_EN_PATTERNS.slice(0, -1)) {
      const m = s.match(re);
      if (m && re.source.startsWith("^(\\d+)")) return rep(...m);
    }
    return s;
  };
  const plural = (n, one, many) => `${n} ${Number(n) === 1 ? one : many}`;
  window.XYNTAL_EN_PATTERNS = [
    [/^(\d+) Stimmen$/, (_, a) => `${a} votes`],
    [/^(\d+) Anhänge in der App$/, (_, a) => `${a} attachments in the app`],
    [/^Zuletzt aktualisiert: (.+)$/, (_, a) => `Last updated: ${a}`],
    [/^Woche (\d+)$/, (_, a) => `Week ${a}`],
    [/^(\d+) von (\d+)$/, (_, a, b) => `${a} of ${b}`],
    [/^(\d+) von (\d+) erledigt$/, (_, a, b) => `${a} of ${b} done`],
    [/^(\d+) von (\d+) Std\.$/, (_, a, b) => `${a} of ${b} hrs`],
    [/^(\d+) von (\d+) Rollen besetzt$/, (_, a, b) => `${a} of ${b} roles filled`],
    [/^(\d+) Std\.$/, (_, a) => `${a} hrs`],
    [/^(\d+) Std\.\/Woche$/, (_, a) => `${a} hrs/week`],
    [/^(\d+) offene Rolle$/, (_, n) => `${n} open role`],
    [/^(\d+) offene Rollen$/, (_, n) => `${n} open roles`],
    [/^(\d+) Bewerbung$/, (_, n) => `${n} application`],
    [/^(\d+) Bewerbungen$/, (_, n) => `${n} applications`],
    [/^Kommentare \((\d+)\)$/, (_, n) => `Comments (${n})`],
    [/^(.+) · (\d+) neu$/, (_, a, n) => `${a} · ${n} new`],
    [/^(\d+)–(\d+) Std\.$/, (_, a, b) => `${a}–${b} hrs`],
    [/^Bewerbungen ansehen \((\d+)\)$/, (_, n) => `View applications (${n})`],
    [/^Als besetzt markieren: (.+)$/, (_, a) => `Mark as filled: ${a}`],
    [/^Besetzung aufheben: (.+)$/, (_, a) => `Mark as open: ${a}`],
    [/^≈ (\d+) Std\.\/Woche$/, (_, a) => `≈ ${a} hrs/week`],
    [/^(\d+) Std\.\/Woche gemeinsam$/, (_, a) => `${a} hrs/week combined`],
    [/^(\d+) Std\.\/Woche · (.+)$/, (_, a, b) => `${a} hrs/week · ${t(b)}`],
    [/^(.+) · (\d+) Std\.\/Woche$/, (_, a, b) => `${t(a)} · ${b} hrs/week`],
    [/^(\d+) Vorschläge$/, (_, a) => `${a} suggestions`],
    [/^(\d+) Vorschläge für (.+)\.$/, (_, a, b) => `${a} suggestions for ${t(b)}.`],
    [/^> scanne Profile für (.+) …$/, (_, a) => `> scanning profiles for ${t(a)} …`],
    [/^(.+) ist im Team$/, (_, a) => `${a} is on the team`],
    [/^Anfrage an (.+) gesendet …$/, (_, a) => `Request sent to ${a} …`],
    [/^(.+) will bei (\S+) als (.+) mitmachen\.$/, (_, a, p, b) => `${a} wants to join ${p} as ${t(b)}.`],
    [/^Öffne die E-Mail an (.+) und klicke auf den Bestätigungslink\. Erst dann bist du auf der Warteliste\.$/, (_, email) => `Open the email sent to ${email} and click the confirmation link. Only then are you on the waitlist.`],
    [/^(.+?) Nach deiner Bestätigung bist du Nr\. ([\d.]+) auf der Warteliste\.$/, (_, a, n) => `${t(a)} Once you confirm, you're no. ${n.replace(/\./g, ",")} on the waitlist.`],
    [/^(.+): (nach oben|nach unten)$/, (_, a, d) => `${t(a)}: ${d === "nach oben" ? "move up" : "move down"}`],
    [/^Nach deiner Bestätigung bist du Nr\. ([\d.]+) auf der Warteliste\.$/, (_, n) => `Once you confirm, you're no. ${n.replace(/\./g, ",")} on the waitlist.`],
    [/^Dein Link xyntal\.de\/(\S+) ist reserviert\.$/, (_, h) => `Your link xyntal.de/${h} is reserved.`],
    [/^xyntal\.de\/(\S+) ist leider schon vergeben\. Du kannst dir nach dem Start einen anderen aussuchen\.$/, (_, h) => `xyntal.de/${h} is already taken. You can pick another one after launch.`],
    [/^Deine Karte ist jetzt unter xyntal\.de\/(\S+) zu sehen\.$/, (_, h) => `Your card is now live at xyntal.de/${h}.`],
    [/^Gespeichert\. Dein Profil ist unter xyntal\.de\/(\S+) zu sehen\.$/, (_, h) => `Saved. Your profile is live at xyntal.de/${h}.`],
    [/^Match mit (.+)\.$/, (_, a) => `Match with ${a}.`],
    [/^: (.+) – (passt teilweise|passt)$/, (_, a, b) => `: ${t(a)} – ${b === "passt" ? "fits" : "partly fits"}`],
    [/^Besetzt: (.+)$/, (_, a) => `Filled: ${a}`],
    [/^Ersetzt (.+)$/, (_, a) => `Replaces ${a}`],
    [/^(.+) aus dem Team entfernen$/, (_, a) => `Remove ${a} from the team`],
    [/^zuständig: (.+)$/, (_, a) => `assigned: ${a}`],
    [/^Weiter suchen: (.+)$/, (_, a) => `Keep searching: ${t(a)}`],
    [/^(.+) ist nicht mehr im Team\. (.+) ist wieder offen\.$/, (_, a, b) => `${a} is no longer on the team. ${t(b)} is open again.`],
    [/^(.+) ersetzt (.+) für (.+)\.$/, (_, a, b, c) => `${a} replaces ${b} for ${t(c)}.`],
    [/^(.+) ist jetzt im Team für (.+)\.$/, (_, a, b) => `${a} is now on the team for ${t(b)}.`],
    [/^Dein Demo-Team aus der Auswahl oben: (.+)\.$/, (_, a) => `Your demo team from above: ${a}.`],
    [/^vor (\d+) Min\.$/, (_, a) => `${a} min ago`],
    [/^vor (\d+) Std\.$/, (_, a) => `${a} h ago`],
    [/^vor (\d+) Tagen$/, (_, a) => `${a} days ago`],
    [/^(.+) · ungelesen$/, (_, a) => `${t(a)} · unread`],
    [/^(.+) · öffentlich$/, (_, a) => `${t(a)} · public`],
    [/^(\d+) (Zusage|Zusagen)( · Du bist dabei)?$/, (_, n, __, me) => plural(n, "RSVP", "RSVPs") + (me ? " · you're in" : "")],
    [/^(.+) Uhr$/, (_, a) => a],
    [/^„(.+)“ ist gespeichert\.$/, (_, a) => `“${a}” has been saved.`],
    [/^Rolle (\d+)$/, (_, a) => `Role ${a}`],
    [/^noch (\d+) Zeichen bis zum Minimum$/, (_, a) => `${a} more characters to go`],
    [/^Erzähl mir etwas mehr, warum du dabei sein solltest – mindestens (\d+) Zeichen\.$/, (_, a) => `Tell me a bit more about why you should be in – at least ${a} characters.`],
    [/^Wir haben dir einen Code an (.+) geschickt\.$/, (_, a) => `We've sent a code to ${a}.`],
    [/^Für mein Projekt suche ich Menschen für: (.+)\.$/, (_, a) => `For my project I'm looking for people for: ${a.split(", ").map(t).join(", ")}.`],
    [/^Dein Profil wartet noch auf Freigabe\. Danach kannst du (.+) und siehst alle Inhalte\.$/, (_, a) => `Your profile is still awaiting approval. After that you can ${t(a)} and see all content.`],
    [/^, um (.+) und alles zu sehen\.$/, (_, a) => ` to ${t(a)} and see everything.`],
    [/^Eingabe in deiner Geräte-Zeitzone: (.+)\.$/, (_, a) => `Entered in your device time zone: ${a}.`],
    [/^Nichts gefunden für „(.+)“$/, (_, a) => `Nothing found for “${a}”`],
    [/^Du: (.*)$/, (_, a) => `You: ${a}`],
    [/^(.+) Die alte Datei konnte nicht aufgeräumt werden\. Versuch es über „Alte Dateien aufräumen“ erneut\.$/, (_, a) => `${t(a)} The old file couldn't be cleaned up. Try again via “Clean up old files”.`],
    // Allgemein: „A · B · C“ – jeden Teil einzeln übersetzen
    [/^[^·]+( · [^·]+)+$/, (s) => { const parts = s.split(" · "); const out = parts.map(t); return out.some((p, i) => p !== parts[i]) ? out.join(" · ") : undefined; }],
  ];
})();
